    "de": "euch",
    "lv": "Tu • Tu",
    "level": "A1",
    "study": {
      "id": "a1-euch",
      "layout": "standardStudy",
      "translation": "Tu • Tu",
      "explanation": "„euch” este un pronume de persoana a 2-a plural. Se folosește atât ca complement direct (unde?) – „tu”, cât și ca complement indirect (cui?) – „către tine”.",
      "examples": [
        {
          "de": "Ich sehe euch.",
          "lv": "Te văd"
        },
        {
          "de": "Ich helfe euch.",
          "lv": "Te ajut"
        },
        {
          "de": "Ich gebe euch das Buch.",
          "lv": "Iti dau o carte"
        },
        {
          "de": "Ich danke euch.",
          "lv": "Iti multumesc"
        },
        {
          "de": "Ihr erinnert euch.",
          "lv": "Iti amintesti"
        }
      ],
      "comparison": [
        {
          "word": "ihr",
          "meaning": "Tu",
          "example": "Ihr seid freundlich. = Jūs esat draudzīgi."
        },
        {
          "word": "euch",
          "meaning": "Tu/la tine",
          "example": "Ich helfe euch. = Es jums palīdzu."
        },
        {
          "word": "euer",
          "meaning": "A ta",
          "example": "Das ist euer Haus. = Tā ir jūsu māja."
        }
      ],
      "info": [
        "Ihr = tu (forma subiectului propoziției)",
        "Euch = tu (unde? formă) / tu (cui? formă)",
        "Euer = dvs. (forma posesivă)"
      ],
      "tip": {
        "text": "„euch” răspunde la întrebarea „cui?” sau este complementul direct în propoziții cu „tu”.",
        "example": "Te ajut. = Ich helfe euch. te văd = Ich sehe euch. iti spun eu. = Ich erzähle euch."
      },
      "accents": {
        "blue": [
          "Ihr"
        ],
        "yellow": [
          "Euch"
        ],
        "green": [
          "Euer"
        ]
      }
    }
