      "explanation": [
        "Ideea principală: der Mann poate însemna bărbat (sex) sau soț (soț).",
        "Dacă este pur și simplu o chestiune de gen sau persoană, Mann = bărbat.",
        "Pentru un soț, der Mann = soț (mein Mann = soțul meu).",
        "Pronumele posesiv (mein/dein/ihr Mann) înseamnă aproape întotdeauna soț - soț.",
        "Plural: die Männer.",
        "Forma feminină die Frau are același dublu sens: femeie ȘI soție."
      ],
