      "explanation": [
        "Ideea principală: Plural - vorbește despre mai mult de o persoană. Verbul se termină în -en: kochen, essen, gehen.",
        "Sie înseamnă în principal: o femeie.",
        "Caracterizat adesea prin: verb singular (-t).",
        "Sie înseamnă în principal: mai multe persoane.",
        "Caracterizat adesea prin: verb la plural (-en).",
        "Sie înseamnă în principal: adresa politicoasă.",
        "Descris adesea: neapărat cu S majusculă.",
        "Micul sie înseamnă ea când verbul este singular (Sie kocht = ea gătește)."
      ],
