        "Sitzen este folosit pentru o persoană sau un animal care stă.",
        "Uneori, sitzen înseamnă și a fi într-un anumit loc, dar în A1 sensul principal este a sta.",
        "Este important să distingem: sitzen = sta, stehen = stand, liegen = culca."
